  if(owner_==Owner::None){auto q=fg.request();if(q.kind!=F::RequestKind::MidiHandler)return Route::External;bool ok=false;handler_=q.handler;switch(q.handler){case F::MidiHandler::ControlChange:ok=control_.start(q.channel,q.payload);owner_=Owner::Control;break;case F::MidiHandler::ProgramChange:ok=program_.start(q.channel,q.payload);owner_=Owner::Program;break;case F::MidiHandler::SysExStart:ok=sysex_.start(S::Kind::Start,q.payload);owner_=Owner::SysEx;break;case F::MidiHandler::SysExEnd:ok=sysex_.start(S::Kind::End,q.payload);owner_=Owner::SysEx;break;default:handler_=F::MidiHandler::Unknown;return Route::External;}if(!ok){owner_=Owner::None;handler_=F::MidiHandler::Unknown;return Route::Invalid;}}
  if(owner_==Owner::Control){auto r=control_.refreshRequest();using Ch=VoiceRefreshTask::Child;if(r.child==Ch::DspSelect)return control_.beginRefreshDsp(dsp,d)?Route::Ready:Route::Invalid;if(r.child==Ch::Update)return control_.beginRefreshDepth(depth_,dsp,d)?Route::Ready:Route::Invalid;if(r.child!=Ch::None)return Route::External;auto q=control_.request();switch(q.service){case C::Service::None:return Route::Ready;case C::Service::Volume:if(dsp.active()||!volume_.start(q.value))return Route::Invalid;return Route::Ready;case C::Service::RefreshModulation:case C::Service::RefreshBreath:return control_.beginRefresh(refresh_,d)?Route::Ready:Route::Invalid;case C::Service::CommitModulation:case C::Service::CommitBreath:return control_.beginExpressionValues(values_,dsp,d)?Route::Ready:Route::Invalid;case C::Service::ReleaseVoices:return control_.beginVoices(voice_,dsp,d)?Route::Ready:Route::Invalid;case C::Service::AllSoundOff:return control_.beginAllSoundOff(allSound_,dsp,d)?Route::Ready:Route::Invalid;case C::Service::ReleaseSustain:return control_.beginSustainRelease(sustain_,dsp,d)?Route::Ready:Route::Invalid;case C::Service::UpdateVoices:if(!voiceServices.startParameterRefresh())return Route::Invalid;parameter_=true;return Route::Ready;default:return Route::External;}}
