 Result advanceBefore(F&fg,ControllerDeviceState&d,ControllerInterruptRuntime&irq,ControllerDspTransferRuntime&dsp,V&voiceServices,unsigned budget){if(bound_!=&d)return {0,false,Block::NotBound};if(owner_==Owner::None)return {0,false,Block::Inactive};if(volume_.active()){auto r=volume_.advanceBefore(d,irq,dsp,budget);if(r.returned&&!control_.completeService(C::Service::Volume))return {r.clocks,false,Block::Invalid};return {r.clocks,false,r.blocked==ControllerStartupVolumeRuntime::Block::NeedsInterrupt?Block::NeedsInterrupt:r.blocked==ControllerStartupVolumeRuntime::Block::DspBusy?Block::External:Block::None};}if(display_.active()){auto r=display_.advanceBefore(d,irq,*displayPanel_,*displayNumeric_,*displayLcd_,budget);if(r.returned&&!finishDisplay())return {r.clocks,false,Block::Invalid};return {r.clocks,false,r.blocked==ControllerStartupDisplayRuntime::Block::NeedsInterrupt?Block::NeedsInterrupt:r.blocked==ControllerStartupDisplayRuntime::Block::AwaitService||r.blocked==ControllerStartupDisplayRuntime::Block::ServiceBusy?Block::External:Block::None};}if(panel_){auto r=panelRefresh_.advanceBefore(d,irq,*panel_,dsp,budget);if(r.returned){auto parent=panelParent_;panel_=nullptr;panelParent_=Owner::None;bool ok=parent==Owner::Control?control_.completeService(C::Service::Panel):parent==Owner::Program?program_.completeService(P::Service::RefreshPanel):sysex_.completeService(S::Service::RefreshPanel);if(!ok)return {r.clocks,false,Block::Invalid};}if(r.blocked==ControllerPanelRefreshRuntime::Block::UnsupportedHandler){panelUnsupported_=true;return {r.clocks,false,Block::External};}return {r.clocks,false,r.blocked==ControllerPanelRefreshRuntime::Block::NeedsInterrupt?Block::NeedsInterrupt:r.blocked==ControllerPanelRefreshRuntime::Block::ServiceBusy?Block::External:Block::None};}if(parameter_){auto r=voiceServices.advanceParameterRefresh(d,irq,dsp,budget);if(r.returned){parameter_=false;if(!control_.completeService(C::Service::UpdateVoices))return {r.clocks,false,Block::Invalid};}return {r.clocks,false,r.blocked==ControllerVoiceRefreshRuntime::Block::NeedsInterrupt?Block::NeedsInterrupt:r.blocked==ControllerVoiceRefreshRuntime::Block::AwaitChild?Block::External:Block::None};}unsigned clocks=0;bool done=false;Block block=Block::None;if(owner_==Owner::Control){auto r=control_.advanceBefore(d,irq,budget);clocks=r.clocks;done=r.returned;block=r.blocked==C::Block::NeedsInterrupt?Block::NeedsInterrupt:r.blocked==C::Block::AwaitService||r.blocked==C::Block::AwaitRefreshChild?Block::External:r.blocked==C::Block::None?Block::None:Block::Invalid;}else if(owner_==Owner::Program){auto r=program_.advanceBefore(d,irq,budget);clocks=r.clocks;done=r.returned;block=r.blocked==P::Block::NeedsInterrupt?Block::NeedsInterrupt:r.blocked==P::Block::AwaitService?Block::External:r.blocked==P::Block::None?Block::None:Block::Invalid;}else{auto r=sysex_.advanceBefore(d,irq,budget);clocks=r.clocks;done=r.returned;block=r.blocked==S::Block::NeedsInterrupt?Block::NeedsInterrupt:r.blocked==S::Block::AwaitService?Block::External:r.blocked==S::Block::None?Block::None:Block::Invalid;}if(done){auto handler=handler_;owner_=Owner::None;handler_=F::MidiHandler::Unknown;if(!fg.completeMidiHandler(handler))return {clocks,false,Block::Invalid};return {clocks,true,Block::None};}return {clocks,false,block};}
